    fullDescription: 'Редкий маршрут, где за один день можно увидеть и услышать оба моря — Азовское и Чёрное.\n\n«Поместье Голубицкое» — современная виноделья на берегу Азовского моря. Красивая ухоженная территория для прогулки и фотографий, множество фотозон. Желающие могут заказать экскурсию по производству и дегустацию вин (2500 ₽, или только экскурсия без дегустации 1100 ₽). После прогулки по виноделье — берег Азовского моря: подышать солёным воздухом и послушать прибой.\n\nБолотные кипарисы в Сукко — затопленные деревья стоят прямо в воде, зрелище совершенно нереальное по красоте. Сейчас они в воде — это самый зрелищный период. Можно подъехать к стволам на катамаране и рассмотреть вблизи.\n\nСупсех — «край земли» побережья. Обрывистые берега с 800 ступенями вниз к морю, знаменитые Ласточкины Гнёзда (природные скальные образования — не путать с крымскими), гора Лысая с невероятными панорамами. С краёв смотровых часто видно дельфинов. Желающие могут спуститься к морю. Завершение дня — закат над Чёрным морем.',
