    fullDescription: 'Тур-релакс для тех, кто хочет горный воздух и тёплую воду — всё в один день, без суеты.\n\nПо дороге из Краснодара экскурсовод рассказывает об истории тех мест, куда вы едете — горы, ущелья, история Гуамки и окрестностей.\n\nГуамское ущелье — узкий живописный каньон вдоль реки Курджипс с отвесными стенами высотой до 400 метров. Первая часть пути — на паровозике по узкоколейке (1000 ₽ взр / 800 ₽ дет, по желанию), дальше пешком по живописной тропе около 4–5 км в оба конца. Ущелье красиво в любое время года: весной — водопады, летом — прохлада, осенью — краски.\n\nПосле прогулки по ущелью — обед в Гуамке (можно взять с собой или поесть в местном кафе).\n\nФинал дня — термальная база: 1,5 часа в горячих бассейнах (600 ₽ взр / 300 ₽ дет). Горячая вода после 5 км по каньону — ощущение, ради которого стоит ехать.\n\nВозвращение в Краснодар к 20:30–21:00.',
