    fullDescription: 'Романтичный тур для тех, кто ценит красивые места, хорошее вино и неспешный ритм — три разных адреса с разным настроением в один маршрут.\n\n«Долина Лефкадия» — одна из лучших виноделен Кубани, загадочная и ухоженная. Парк с лозами, дегустационный зал, хорошая кухня. Вход 200 ₽, экскурсия с дегустацией по желанию (1500 ₽). Здесь делают вина, которые регулярно берут медали на международных конкурсах.\n\nСтарый Парк в Кабардинке — авторский частный парк Александра Алексеева с европейской атмосферой: витражи, фонтаны, скульптуры, кафе под открытым небом. Весной парк в цвету. Вход 1000 ₽ взр / 500 ₽ дет.\n\nШато-Пино — финал дня, и какой. Улиточная ферма и винодельня в невероятно красивом месте в окрестностях горы Колдун. Виды — нереальные, а какая дегустация: улитки «эскарго» и вино собственного производства. Закат с террасы Шато-Пино — отдельное событие. Дегустация улиток + вино — 1200 ₽, только улитки — 850 ₽, только вино — 850 ₽.',
