    fullDescription: 'Один из самых разнообразных однодневных маршрутов на черноморском побережье — за один день водопады, дольмены, скальные обрывы и закат у моря.\n\nВодопады реки Жане — живописная тропа через реликтовый лес к нескольким каскадным водопадам. По дороге — «деревня дольменов»: мегалитические каменные сооружения возрастом более 4000 лет. Экологический сбор на тропу — 400 ₽ взр / 200 ₽ дет. Весной, когда реки полноводны, водопады особенно мощные.\n\nГолубая бездна — живописные скальные смотровые над морем: головокружительный вид вниз с обрыва. Для желающих — спуск к морю по тропинке.\n\nСкала Парус — один из главных символов черноморского побережья. Монолитная каменная стена высотой более 20 метров стоит прямо у кромки воды, отделённая от берега узкой полоской пляжа. 17:00–19:00 — закат у скалы, морской воздух, тишина. Вечернее освещение делает Парус особенно фотогеничным.',
