    fullDescription: 'Девять дней, которые вмещают два совершенно разных мира — имперский Петербург и дикую Карелию. Большое путешествие из Краснодара на комфортабельном автобусе.\n\nПетербург — четыре насыщенных дня. Автобусная обзорная экскурсия: Дворцовая площадь, Адмиралтейство, Исаакиевская площадь, стрелка Васильевского острова, набережные и дворцы, Летний сад. Исаакиевский собор — 43 вида мрамора в интерьере. Теплоходная экскурсия «Северная Венеция» по рекам и каналам: дворцы, мосты, Нева. Петергоф — Нижний парк с Большим каскадом, фонтаном «Самсон» и фонтанами-шутихами. Царское Село — Екатерининский дворец с Янтарной комнатой и прогулка по парку. Вечером — ночная экскурсия: разводные мосты Петербурга в 1:30 ночи.\n\nКарелия — три дня. Сортавала на берегу Ладоги и Ладожские шхеры на катере: гранитные острова, скалистые берега, северная природа. Горный парк Рускеала — мраморный каньон с изумрудной водой, мрамор отсюда везли для дворцов Петербурга. Водопады Ахвенкоски. Остров Кижи — деревянный погост ЮНЕСКО: 22-главая Преображенская церковь, часовня Архангела Михаила, крестьянские избы. Добираемся на «Комете» — полтора часа по Онежскому озеру, 4 часа на острове. Петрозаводск — Онежская набережная. Гора Сампо, водопад Кивач с дендрарием, древний вулкан Гирвас, первый российский курорт «Марциальные воды» (основан Петром I).\n\nВыезд из Краснодара 30 апреля. Присоединиться можно также из Ростова-на-Дону.',
