    fullDescription: 'Крым за два дня — маршрут, который умещает главное побережье без потери дней на дорогу.\n\nПервый день — Южный берег Крыма: Массандровский дворец — охотничий замок Александра III в горном лесу, окружённый парком с редкими деревьями. Ливадийский дворец — белый итальянский палаццо, летняя резиденция Николая II и место Ялтинской конференции 1945 года, где встретились Сталин, Черчилль и Рузвельт. Ласточкино гнездо на мысе Ай-Тодор — самая узнаваемая панорама Крыма. Большая прогулка по ялтинской набережной вдоль платанов, памятников и старинных купален.\n\nВторой день — Севастополь. Трасса Алушта–Севастополь вдоль моря с остановкой у Форосского храма. Новый Херсонес — грандиозный музейно-храмовый комплекс на 24 гектарах, открытый в 2023 году: 30 уникальных объектов, «оживший» античный город рядом с настоящим Херсонесом Таврическим. Обзорная по Севастополю: Графская пристань, площадь Нахимова, памятник Затопленным кораблям — символ города, Приморский бульвар, Сапун-гора.\n\nВыезд из Краснодара в час ночи — через Крымский мост. Приезжаете утром и сразу начинаете программу.',
