    fullDescription: 'Знаменитый на всю Россию парк, построенный Сергеем Галицким за собственные средства. Концепция — «отрицание реальности городской среды», попытка создать микрокосмос из воды, камня, дерева и растений.\n\nТерритория парка разбита на 30 зон для отдыха: от прогулок с детьми и просмотра кино под открытым небом до скалодрома и скейтпарка. Летний амфитеатр, лабиринты, игровые площадки, кафе, верёвочный панда-парк, террасированный сад, фонтаны, водоёмы, английский парк.\n\nЗа 3–3,5 часа с экскурсоводом вы узнаете: что символизируют локации, откуда привезены деревья и кустарники (география — от Средиземноморья до Японии), кто живёт в водоёмах, как «читать» философию парка. Даже если вы бываете здесь каждую неделю — экскурсия откроет парк заново.\n\nНовый Парк Облаков — соседний парковый комплекс, который органично дополняет территорию. Все ключевые локации осмотрим вместе.',
