    fullDescription: 'Всесвятское кладбище основано в 1830 году — самое массовое захоронение Краснодара, расположенное прямо в центре города. Здесь покоится более 1,2 миллиона человек — столько же, сколько сейчас живёт в городе. Самое старое упоминаемое захоронение — могила казачки Марии Косенко 1832 года.\n\nЭкскурсия — необычный способ рассказать историю города через судьбы горожан: казаки, генералы, купцы, поэты. Легенд, мистики и странных фактов хватает: необъяснимые надписи на памятниках, фейковые захоронения, «могила ведьмы».\n\nНа прогулке узнаете об искусстве эпитафий, надгробиях и оградах, склепах и эффигиях, российской похоронной индустрии XIX века. Почему кладбище называют «кладбищем кочующих монументов». Какие тайны скрывает могила генерала Алексеева — основателя Белой армии. Какое отношение к Краснодару имеет знаменитый французский писатель Анри Труайя.\n\nЧастично сохранились армянское, греческое и офицерское кладбища — каждое со своей историей и архитектурой. Площадь — 500 на 500 метров.',
