    fullDescription: 'Узбекистан — это ожившая восточная сказка: мозаичные медресе, древние цитадели, базары с горами специй и душистый плов в чайхане. За семь дней маршрут проведёт через четыре ключевых города Великого Шёлкового пути — от столичного Ташкента до легендарного Самарканда.\n\nХива — единственный город Узбекистана, где средневековый шахристан Ичан-Кала дошёл до наших дней практически нетронутым. Узкие улочки, минареты, мечети с резными деревянными колоннами и дыхание пустыни. Приветственный национальный ужин в первый вечер в Хиве задаёт настроение всему путешествию.\n\nБухара — город, которому больше тысячи лет. Комплекс Лаби-Хауз, цитадель Арк, мавзолей Саманидов и торговые купола, где можно купить шёлк, керамику и пряности. В советском «Аладдине» снимались именно здесь.\n\nСамарканд — кульминация маршрута. Площадь Регистан — самая роскошная из сохранившихся средневековых площадей Средней Азии, усыпальница Тамерлана Гур-Эмир и один из лучших восточных базаров с самаркандской халвой, курутом и сезонными фруктами.\n\nМежду городами — комфортные поезда и один внутренний перелёт. Авиабилеты из вашего города оплачиваются отдельно — поможем подобрать удобный рейс.',
