    fullDescription: 'Калмыкия — совершенно другой мир на расстоянии одного ночного переезда от Краснодара. Буддийские храмы, бескрайние степи, тюльпановые поля, верблюды и шахматный город — ничего подобного больше нет в европейской части России.\n\nПервый день — Элиста. Фестиваль тюльпанов: степи в апреле покрываются коврами диких тюльпанов всех оттенков — красных, жёлтых, белых. Пешеходная экскурсия по городу: Золотая обитель Будды Шакьямуни — крупнейший буддийский хурул в Европе, Пагода Семи дней, Золотые ворота. Интерактивный музей ойрат-монгольской культуры в Шахматном городе (Сити-Чесс) — стрельба из безопасного лука, национальные костюмы, песни и танцы.\n\nВторой день — Страна Бумба. Выезд в село Адык к природным чудесам Калмыкии: Меклетинское (розовое) озеро с необычным цветом воды, горящий источник — газовый ключ, где можно поджечь воду, поющие барханы — песчаные дюны, издающие звуки при ходьбе. Национальный обед в юрте с песнями, танцами и костюмами. Катание на верблюдах — «кораблях степей».',
