    fullDescription: 'Девять дней, за которые вы увидите всю Беларусь — от советского Минска до средневековых замков, от Брестской крепости до заповедных лесов Беловежской пущи, от литовского Гродно до родины Шагала — Витебска.\n\nМинск встретит широкими проспектами и площадью Независимости с красным костёлом, ратушей на площади Свободы и уютным Троицким предместьем. На следующий день — два замка-жемчужины из списка ЮНЕСКО: Мирский замок с башнями и легендами, Несвижский дворец Радзивиллов с живописными парками и фарным костёлом — первым барочным храмом Речи Посполитой.\n\nСамый насыщенный день — Брест и Беловежская пуща. Героическая Брестская крепость: вход через звезду, монументы «Мужество» и «Жажда», музей с артефактами июня 1941 года. Беловежская пуща — один из старейших лесных массивов Европы, ЮНЕСКО. Зубры, вековые дубы и тишина настоящего леса.\n\nГродно — город литовских князей и польских королей на берегах Немана. Королевский замок, Коложская и Фарная церкви, орган и мощёные улочки. Полоцк — древнейший город Беларуси (780 год): Софийский собор, Спасо-Евфросиниевский монастырь XII века, памятник букве «ў» и географический центр Европы. Витебск — Славянский базар, Летний амфитеатр, музей Шагала и усадьба Ильи Репина в Здравнёво.\n\nВ стоимость входят все входные билеты — от замков и крепостей до музеев и интерактивов. Питание — 6 завтраков и 6 обедов. Проживание в отелях Минска, Гродно и Витебска.',
