    fullDescription: 'Четыре дня в высокогорном Дагестане — маршрут, который собрал самое впечатляющее: заброшенные аулы-призраки, подземные водопады, скальные теснины шириной 2 метра и один из глубочайших каньонов мира.\n\nБаза — Гуниб, горное село на плато с видом на хребты. Первый день: аул Чох — древнейший аул Кавказа с узкими улочками и головокружительными видами. Гамсутль — аварский аул-призрак на высоте 1500 метров, крепость без единого жителя.\n\nВторой день — теснины. Салтинская — пещера с подземным водопадом и рекой, по руслу которой идёшь к свету. Карадахская — «Ворота чудес», каньон высотой 170 метров при ширине 2–4 метра; здесь не бывает солнца и даже в полдень полумрак. Старый Гоор — древние башни и дагестанский Язык тролля.\n\nТретий день — Хунзахское плато. Водопад Тобот — один из высочайших в России. Теснина «Каменная чаша» — скалистые лабиринты, соединённые пещерами. Плато Матлас с Матласским водопадом.\n\nЧетвёртый день — Сулакский каньон глубиной 1900 метров. Катер по каньону, подъём на джипах к смотровым, подвесной мост и комплекс пещер «Нохъо». Выезд домой.',
