    shortDescription: '5 экскурсионных дней в самом западном городе России: обзорная по Калининграду, Янтарный и Балтийск, Зеленоградск и Светлогорск, Куршская коса (ЮНЕСКО), замки и сыроварни.',
    fullDescription: 'Калининград — город, где Россия выглядит как Европа. Готические соборы, янтарные пляжи, рыцарские замки и Куршская коса — природный памятник ЮНЕСКО. Пять полных экскурсионных дней, каждый из которых — отдельное путешествие.\n\nПервый день — обзорная по Кёнигсбергу-Калининграду: площадь Победы, скульптура «Борющиеся зубры», район немецких вилл Амалиенау, Музей янтаря в крепостной башне. Кафедральный собор XIV века с могилой Канта и органным концертом. Музей марципана в Бранденбургских воротах.\n\nЯнтарный — 90% мировых запасов янтаря. Променад, лучший пляж области со знаком «Голубой флаг», мастерские. Балтийск — самый западный город России, база Балтийского флота: цитадель Пиллау XVII века, маяк, Свято-Георгиевский собор, памятник Петру I, лебеди у военных кораблей.\n\nЗеленоградск (Кранц) — «самый кошачий город» с водонапорной башней 1905 года и курортным шармом. Светлогорск (Раушен) — хвойные леса, немецкие домики и янтарные лавки.\n\nКуршская коса — жемчужина Калининградской области, ЮНЕСКО. Песчаный полуостров длиной 98 км. Дюна Эфа — высочайшая точка с панорамой на Балтику и Куршский залив. Загадочный Танцующий лес.\n\nЗамок Шаакен — музей инквизиции, оружейная с рыцарскими шлемами, сыроварня «Шаакендорф» с дегустацией.\n\nДобираться можно поездом из Краснодара (2 дня 5 часов, ~12 000 ₽) или самолётом. В стоимость входят 4 завтрака, 5 обедов и все входные билеты.',
