    fullDescription: 'Девять дней от Тбилиси до Батуми — маршрут для тех, кто хочет увидеть всю Грузию, а не только столицу. Горы, вино, море, пещерные города и три абсолютно разных региона: Кахетия, Самцхе-Джавахети и Аджария.\n\nТбилиси — два дня. Полный день с экскурсоводом: Нарикала, серные бани, Инжировое ущелье, мост Мира, собор Троицы, Мтацминда. Кахетия: Бодбе, Сигнахи, дегустация хлеба и сыра в Бидаури, большая винная дегустация.\n\nМцхета — монастырь Джвари VII века, собор Светицховели XI века, Самтавро и Шиомгвиме. Вардзиа — средневековый пещерный город из 600 пещер-комнат, уходящий на 50 метров вглубь скалы в 8 этажей. Крепость Рабат в Ахалцихе. Вечер в Боржоми — знаменитая вода, парк и архитектура.\n\nКутаиси — храм Баграта, прогулка по старому городу. Батуми — три дня: обзорная по городу с тремя площадями, турецким кварталом и набережной. Скульптура «Али и Нино». Горная Аджария: крепость Гонио, водопады, мост Царицы Тамары.\n\nПроживание: 4 ночи в Тбилиси, 1 ночь в Боржоми, 3 ночи в Батуми. 8 завтраков и приветственный ужин включены.',
