    shortDescription: 'Три жемчужины восточного Крыма за один день: тропа Голицына с бирюзовыми бухтами, Генуэзская крепость в Судаке и вечерняя Феодосия.',
    fullDescription: 'Восточный берег Крыма — совсем другой Крым. Здесь нет дворцов и набережных с колоннадами, зато есть скалы, можжевеловые рощи, средневековые крепости и тихие бухты невероятных оттенков.\n\nНовый Свет — легендарный посёлок, основанный князем Голицыным. Тропа Голицына — самая красивая пешеходная тропа полуострова: вырублена прямо в скале над морем, проходит через Зелёную, Синюю и Голубую бухты. Мыс Капчик разделяет бухты как каменный нож, а можжевеловый воздух считается целебным.\n\nСудак — Генуэзская крепость XIV века. Одна из самых хорошо сохранившихся средневековых крепостей Причерноморья: консульский замок, башни, стены на фоне моря и гор. Место, где чувствуешь себя внутри исторического фильма.\n\nВечерняя Феодосия — прогулка по городу Айвазовского: набережная, старые кварталы, тёплый свет закатного солнца на фасадах.',
