    fullDescription: 'Один из самых насыщенных однодневных маршрутов в Крым — за 24 часа вы увидите восточное побережье полуострова таким, каким его не показывают обычные экскурсии.\n\nРанним утром — смотровая «Звездопад воспоминаний» на перевале: головокружительный обрыв, чистейший горный воздух и панорама, от которой перехватывает дыхание. Далее — посёлок Орджоникидзе у подножия горы Джан-Кутаран. Мыс Бугаз — секретная бухта с «исландским» домиком и шоколадным пляжем, куда добираются только те, кто знает дорогу.\n\nПляж Меганом — одно из самых мистических мест Крыма с невероятно чистой водой. Статуи Моаи — загадочные каменные фигуры на берегу бухты Капсель, словно перенесённые с острова Пасхи. Каждая локация — готовая фотосессия.\n\nВечер — мыс Алчак-Кая в Судаке: лёгкий подъём к Эоловой арфе, закатное солнце над генуэзской крепостью и морем. Ужин в Судаке — завершение идеального крымского дня. Возврат к полуночи.',
