    fullDescription: 'Лазаревский район — одно из самых водопадных мест черноморского побережья. Два ущелья за один день — и каждое со своим характером.\n\nДолина реки Аше, она же Изумрудная долина — подвесные мосты над рекой, реликтовый лес и два мощных водопада. Псыдах — «красивая вода» в переводе с адыгейского — около 30 метров высоты, серебросодержащая вода, которой приписывают целебные свойства. Шапсуг — каскадный водопад высотой около 80 метров, один из самых высоких на побережье. Рядом — древние дольмены, Скала Стариков и загадочная пещера Ведьм.\n\nМамедово ущелье — второе открытие дня. Здесь хранится легенда о старце Мамеде, спасшем свой аул. «Голова Мамеда», «Борода Мамеда», «Мамедова купель» — природные скульптуры из камня и воды. Дольмен «Целитель» — мегалит, к которому приходят за здоровьем.\n\nМаршрут средней сложности — потребуется удобная обувь и готовность к пешим переходам по лесным тропам. Награда — потрясающие виды и ощущение настоящей дикой природы.',
