    shortDescription: 'Опукский заповедник, розовое Кояшское озеро, руины древней Киммерии и цветущие пионы у Белой скалы — весенний Крым во всей красе.',
    fullDescription: 'Этот тур существует только весной — и в нём всё про цвет, свет и масштаб крымской природы.\n\nОпукский природный заповедник — 7,5 километров пешего маршрута с семью остановками, каждая из которых — отдельное открытие. Крепостная цитадель на вершине горы Опук — руины древнего городища. Катакомбный комплекс — вырубленные в скале помещения античных времён. Верхнее плато — здесь стояла столица Киммерии, одного из самых загадочных народов древности. Скала Розовых скворцов — место гнездования тысяч птиц.\n\nГидротермальные разломы, источник с античными колодцами, тропа к Дырчатому мысу — каждый шаг по заповеднику наполнен историей и красотой. Кояшское озеро — розовое солёное озеро, одно из самых необычных мест Крыма: кристаллы соли на берегу, фламинго-розовый цвет воды и аромат фиалок.\n\nНа обратном пути — Белая скала: мощный скальный массив, у подножия которого весной цветут дикие пионы. Лошади на фоне гор, закатное солнце и ужин перед выездом к морю. Домой к полуночи.',
