    fullDescription: 'День, который выглядит как путешествие по Провансу — но всего в паре часов от Краснодара. Три локации, каждая из которых создана для красоты и вина.\n\nШато-Андре — семейная винодельня на хуторе Школьном в Крымском районе. 85 гектаров виноградников, собственная пасека, фермерское кафе и погреб, где вызревает авторское вино. Атмосфера южной Франции: каменные стены, лаванда, деревянные бочки и тишина. Экскурсия с дегустацией — по желанию (2 300 ₽).\n\nУсадьба Семигорье — озеро, виноградники, плодовые сады и ресторан с видом на горы. Здесь время замедляется: прогулка по территории, обед в ресторане, дегустация в исторических подвалах (по желанию, 2 000 ₽). Одно из тех мест, куда хочется вернуться.\n\nАбрау-Дюрсо — вечерняя прогулка у горного озера Абрау. Закатное солнце на воде, виноградники на склонах, свежий горный воздух. Идеальное завершение винного дня.',
