    fullDescription: 'Маршрут для тех, кто хочет по-настоящему почувствовать черноморское побережье — пешком, через сосновый лес, к самым впечатляющим видам.\n\nГолубая бездна — так называют участок побережья между Дивноморским и Джанхотом, где сосновый бор подходит к самому обрыву над морем. Пеший маршрут через пицундские сосны: смотровые площадки на каждом повороте тропы, запах хвои, шум прибоя внизу. Спуск к морю — кристально чистая вода невероятного бирюзового цвета, за которую место и получило своё название. Маршрут занимает около 5 часов.\n\nСкала Парус в Прасковеевке — каменная стена высотой 25 метров и толщиной всего около метра, стоящая у самой кромки воды. Один из самых узнаваемых природных памятников Черноморского побережья. Обед у моря, время на отдых и фото.\n\nГеленджик — завершение дня. Прогулка по знаменитой набережной длиной более 14 километров, кафе, вечернее море. Выезд в 19:00.',
