        description: 'Выезд из Краснодара в 6:00.\n\n9:30 — Шато-Пино, улиточная ферма и винодельня у подножия горы Колдун. Открытая терраса с видом, от которого захватывает дух — горы, море, виноградники. Экскурсия по ферме: вы увидите, как выращивают виноградных улиток, узнаете о процессе приготовления «Эскарго» по французским рецептам. Дегустация улиток в паре с авторским вином — по желанию (1 200 ₽). Прогулка по территории: музей виноделия, виноградники на склоне, фотозоны.\n\n12:00 — переезд в Кабардинку. По пути — остановки на панорамных смотровых площадках с видом на Цемесскую бухту, Новороссийск и побережье. Каждая смотровая — отдельная фотосессия.\n\n13:00 — Старый Парк в Кабардинке (вход 1 000 ₽ взрослые / 500 ₽ дети). Единственный на юге России тематический архитектурный парк: египетский храм, средневековый замок с настоящими витражами, японский сад с прудом, античная колоннада, фонтаны и скульптуры. Каждый уголок — произведение искусства. Набережная Кабардинки — время на прогулку и обед.\n\n16:00 — Геленджик. 16:30–19:00 — свободное время: набережная, кафе у моря, прогулка по городу, вечерний Геленджик.\n\n19:00 — выезд. Возвращение в Краснодар к ~22:00.',
